#!/usr/bin/env node
// scripts/lint-plan-index.mjs  (plan 249 — flipped to regenerate-and-diff)
//
// docs/INDEX.md's active plan-bullet region (between the INDEX:PLANS sentinels)
// is GENERATED by scripts/build-index.mjs from each plan's `summary:` frontmatter
// + its git location. This pre-push guard no longer hand-checks orphans / broken
// pointers / line length — it simply asserts the committed INDEX equals what the
// generator would produce. Drift means exactly one thing:
//
//     "you moved or authored a plan but didn't regenerate docs/INDEX.md."
//
//   Fix:  node scripts/build-index.mjs && git add docs/INDEX.md
//
// Crucially, build-index sources plan paths from `git ls-files`, NOT a filesystem
// walk — so an UNTRACKED plan doc another parallel session dropped in ready/ is
// invisible here and can NEVER gate your push. That kills the orphan-paralysis
// trigger (the readdir-based Check A in the pre-249 lint) where a foreign
// working-tree file blocked an unrelated session's push.
//
// SECOND check (archive-consistency): build-index --check only validates the
// GENERATED active region. It is blind to the hand-maintained archive narrative
// that lives AFTER the INDEX:PLANS-END sentinel — which is exactly where two real
// stranding bugs hid:
//   - plan 256: INDEX said "archived", but the .md was still tracked in
//     in-progress/ (the INDEX bullet moved via index.mjs, the `git mv` of the file
//     never landed) → the plan was double-listed and /state misreported it.
//   - plan 245-DQ: INDEX said "archived", but the .md was never git-tracked at all
//     — the broad `archive/` .gitignore rule silently rejected the `git add`.
// This check enforces the invariant: every plan named in the archive narrative
// MUST be tracked at plans/archive/<name>, and nowhere else.
//
// FOURTH check (category-subfolder nesting, plan 2678): a plan sits flat under its status
// folder or ONE level down in a lowercase `[a-z0-9-]+` category folder — and never under
// the flat-only archive/. See findNestingViolations / checkNestingInvariant below.
//
// THIRD check (stage/folder invariant, plan 1371 D7): pending-approval/ (the sanctioned
// resting spot for a freshly minted, not-yet-reviewed plan) must hold ONLY `stage: stub`
// plans — a `stage: specced` plan there means spec-pass finished but board-pass never
// routed it out. See findStageFolderViolations / checkStageFolderInvariant below.
//
// Exit codes:  0 clean · 1 drift / archive-inconsistency / stage-folder violation
//              (push blocked) · 2 error.

import { execFileSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { gitRepoIsolatedEnv } from './child-env.mjs';
import {
  readFrontmatterScalar,
  nextHeadingBoundary,
  sectionBounds,
  stripFencedBlocks,
  classifyPlanPaths,
  ARCHIVE_FOLDER,
  PENDING_APPROVAL_FOLDER,
  READY_FOLDER,
} from './build-index-lib.mjs';
import {
  computeDriftIsInherited,
  checkWorktreeCoordDocStale,
  formatStaleWorktreeCoordDocMessage,
} from './drift-attribution-lib.mjs';
import { markPushTelemetryHit } from './push-telemetry-lib.mjs';
import { repoRootFrom } from './scripts-anchor.mjs';

const REPO_ROOT = repoRootFrom(dirname(fileURLToPath(import.meta.url)));
const BUILD_INDEX = join(REPO_ROOT, 'scripts', 'build-index.mjs');
const INDEX_REL = 'docs/INDEX.md';
const INDEX_PATH = join(REPO_ROOT, INDEX_REL);
const PLANS_PREFIX = 'docs/superpowers/plans/';
const PLANS_END = '<!-- INDEX:PLANS-END -->';

// Every plan file `git ls-files` tracks under docs/superpowers/plans/ (repo-relative
// paths). Shared by checkArchiveConsistency and checkStageFolderInvariant below — both
// need the identical tracked-file enumeration for two different questions (archive-
// narrative consistency vs. the stage/folder invariant); previously each re-issued its
// own `git ls-files` call + loop, which could silently drift if one's pathspec/prefix
// changed and the other's didn't (review fix K). Fails soft ([]) on any git error.
function listTrackedPlanFiles() {
  try {
    return execFileSync('git', ['ls-files', `${PLANS_PREFIX}*.md`], {
      cwd: REPO_ROOT,
      encoding: 'utf8',
      env: gitRepoIsolatedEnv(),
    })
      .split('\n')
      .filter(Boolean);
  } catch {
    return [];
  }
}

// Every plan named in the plans-archive narrative must be git-tracked at
// plans/archive/<name> and nowhere else. Only flags ACTIONABLE strandings:
//   - tracked in an active folder (256-type: bullet moved, `git mv` didn't), or
//   - present on disk in archive/ but untracked (245-DQ-type: the archive/
//     .gitignore rule blocked the add).
// A narrative entry with NO file on disk is intentional history (a plan archived
// + later deleted/consolidated long ago) — skipped, never gates a push. That
// mirrors the active-region rule "untracked/foreign docs never gate your push":
// the guard catches your own half-finished archive, not the historical ledger.
//
// plan 2052 R2: bound the archive-narrative region (see the call site's own
// comment for what the region IS) at the next heading of level <= 2 — the
// containing `## Plans` heading's level — via the shared build-index-lib
// scanner. The paragraph anchor (finding the region's START) stays inline at
// the call site; only the BOUNDARY past it delegates here, keeping output
// byte-identical for the real file (the region carries zero interior
// headings today) while gaining fence-awareness for free from the shared
// primitive.
//
// Takes `afterPlansEnd` (everything past the INDEX:PLANS-END sentinel) and
// `fromIndex` (the intro paragraph's own offset into it) SEPARATELY, rather
// than a pre-sliced `afterPlansEnd.slice(fromIndex)` substring — review
// finding, plan 2052: nextHeadingBoundary's fence-tracking is only correct
// when it scans from the text's TRUE start, and a caller that pre-slices
// away everything before `fromIndex` erases whatever fence state a fence
// opened earlier (e.g. inside the generated Plans-bullet region) would have
// left behind at that point.
export function boundArchiveRegion(afterPlansEnd, fromIndex) {
  return afterPlansEnd.slice(fromIndex, nextHeadingBoundary(afterPlansEnd, fromIndex, 2));
}

// Returns { code, untrackedStrand } (plan 1650 review [1]): the 245-DQ-type violation
// (file on disk in archive/ but never git-tracked — the .gitignore rule blocked the add)
// is detected via existsSync against THIS working tree, is invisible to both `git diff`
// and `git status` (gitignored), and is therefore ALWAYS local to this checkout — the
// inherited-drift tolerance in main() must never wave it through, so it is flagged
// out-of-band from the exit code.
export function checkArchiveConsistency() {
  let index;
  try {
    index = readFileSync(INDEX_PATH, 'utf8');
  } catch {
    return { code: 0, untrackedStrand: false, indexContent: null }; // no INDEX → nothing to check
  }
  // indexContent is threaded through so a caller that also needs a staleness check
  // (reportIndexStalenessIfAny below) can reuse this read instead of a second
  // ~840KB readFileSync of the same file (plan 2099 review [1]).
  const strict = (code) => ({ code, untrackedStrand: false, indexContent: index });
  const endIdx = index.indexOf(PLANS_END);
  if (endIdx === -1) return strict(0); // legacy INDEX without sentinels

  // Bound the region to the plans-archive narrative ONLY: from its intro line
  // ("Moved to `docs/superpowers/plans/archive/`") to the next markdown header.
  // Anything past that (## Reference / Handoffs / Runbooks / Architecture) lists
  // runbook + doc .md refs that must NOT be read as archived plans.
  const after = index.slice(endIdx);
  const introMatch = /^Moved to `docs\/superpowers\/plans\/archive\//m.exec(after);
  if (!introMatch) return strict(0);
  const region = boundArchiveRegion(after, introMatch.index);

  // `^- \`name.md\`` is line-anchored, so a mid-line backtick ref (e.g. "...spun
  // out to `ready/260-…md`") never matches.
  const archived = [
    ...new Set([...region.matchAll(/^- `([^`]+\.md)`/gm)].map((m) => m[1].split('/').pop())),
  ];
  if (!archived.length) return strict(0);

  const tracked = listTrackedPlanFiles();
  const byName = new Map();
  for (const p of tracked) byName.set(p.split('/').pop(), p);

  const violations = [];
  let untrackedStrand = false;
  for (const name of archived) {
    const path = byName.get(name);
    if (path && path.startsWith(`${PLANS_PREFIX}archive/`)) continue; // correctly archived
    if (path) {
      const folder = path.slice(PLANS_PREFIX.length).split('/')[0];
      violations.push(
        `  ${name}: archived in docs/INDEX.md but the file is tracked in ${folder}/ — ` +
          `finish the move: node scripts/move-plan.mjs ${name} archive`,
      );
    } else if (existsSync(join(REPO_ROOT, PLANS_PREFIX, ARCHIVE_FOLDER, name))) {
      untrackedStrand = true; // local-by-nature: on THIS disk, invisible to git diff/status
      violations.push(
        `  ${name}: in plans/archive/ on disk but NOT git-tracked — the broad archive/ ` +
          `.gitignore rule blocked the add. Recover: git add ${PLANS_PREFIX}archive/${name}`,
      );
    }
    // else: no file on disk + not tracked → historical-only narrative entry, skip.
  }
  if (violations.length) {
    console.error('');
    console.error(
      'lint-plan-index: archive-consistency FAILED — plans listed as archived in docs/INDEX.md ' +
        'but stranded outside plans/archive/:',
    );
    violations.forEach((v) => console.error(v));
    console.error('');
    return { code: 1, untrackedStrand, indexContent: index };
  }
  return strict(0);
}

// D7 (plan 1371): pending-approval/ holds ONLY un-reviewed (`stage: stub`) plans — a
// `stage: specced` plan resting there means spec-pass already reviewed the framing but the
// board-pass step never routed it out (a stale/forgotten move). The MIRROR rule ("a `stage:
// stub` plan may not sit in `ready/`") is already enforced at WRITE time by assertSpecReviewOk
// (move-plan.mjs's promotion gate) and the `--ready` mint gate (next-plan-id.mjs's doClaim) —
// this is the READ-time backstop for the OTHER direction only, so it never duplicates those
// gates. A plan with NO `stage` key at all (a legacy plan minted before plan 1292) is not
// flagged — the same grandfather clause `specReviewGateErrorFromValues` (build-index-lib.mjs)
// already documents. Pure core (entries = [{ path, content }], repo-relative path); the IO
// wrapper below feeds it every tracked plan file, mirroring findExecModelDrift's split
// (lint-filename-execmodel-drift.mjs) so this stays unit-testable without a real git repo.
//
// STAGE_FOLDER_SCOPE is the single folder this invariant is scoped to — exported so a
// second write-time enforcer (board-write-gate.mjs's `gateAppliesToFolder`, plan 2426
// review round 2) can read the scope from the module that owns it instead of hand-rolling
// its own copy of the literal.
export const STAGE_FOLDER_SCOPE = PENDING_APPROVAL_FOLDER;

export function findStageFolderViolations(entries) {
  const violations = [];
  for (const { path, content } of entries) {
    const rel = path.slice(PLANS_PREFIX.length);
    const status = rel.split('/')[0];
    // The invariant is scoped to pending-approval/ ONLY — every other folder (ready/,
    // in-progress/, waiting-*/, archive/, and parked/ since plan 1426) is out of scope
    // here by construction, never checked. parked/ in particular must accept ANY stage
    // (a plan can be frozen mid-review, before or after spec-pass) — this early
    // `continue` already guarantees that without a parked-specific carve-out.
    if (status !== STAGE_FOLDER_SCOPE) continue;
    const stage = readFrontmatterScalar(content, 'stage').toLowerCase();
    if (stage && stage !== 'stub') {
      violations.push(
        `  ${rel.split('/').pop()}: stage: ${stage} in pending-approval/ — route it out ` +
          `(node scripts/move-plan.mjs <id> ready|<waiting-state>); a specced plan must not ` +
          `rest in the stub pen.`,
      );
    }
  }
  return violations;
}

// Every tracked plan file as { path, content }, tolerating a half-staged `git mv` (a path
// listed by `git ls-files` whose working-tree file is momentarily missing is skipped, not a
// crash — not this lint's concern; a genuine strand there is caught by the archive check).
// ONE copy, shared by the two pure-check IO wrappers below (plan 3943 review round 1: the
// inherited-premises wrapper had duplicated it verbatim).
function trackedPlanEntries() {
  const entries = [];
  for (const rel of listTrackedPlanFiles()) {
    try {
      entries.push({ path: rel, content: readFileSync(join(REPO_ROOT, rel), 'utf8') });
    } catch {
      /* half-staged mv — not this lint's concern */
    }
  }
  return entries;
}

// IO wrapper: every tracked plan file's { path, content }, fed to the pure check above.
export function checkStageFolderInvariant() {
  const violations = findStageFolderViolations(trackedPlanEntries());
  if (violations.length) {
    console.error('');
    console.error(
      'lint-plan-index: stage/folder invariant FAILED — pending-approval/ must hold only ' +
        'stage: stub plans:',
    );
    violations.forEach((v) => console.error(v));
    console.error('');
    return 1;
  }
  return 0;
}

// ── Inherited-premises invariant (plan 3943) ───────────────────────────────
// A plan that belongs to a PROGRAM inherits mechanisms it never states — it assumes them
// because the parent program assumed them — and the spec-pass C1 premise check therefore
// never sees them. That is exactly how plan 3858 passed a real spec-pass (53 cited steps
// verified, three premises corrected) and still missed the fatal one: an apply-side hold
// never reaches a judge in any pass, an assumption of the archived parent program 3796.
// So a program child writes its inherited premises DOWN, one line each, and C1 verifies
// them like any other claim.
//
// Scoped to `ready/` ONLY, and deliberately so: `ready/` is the drain's intake, the last
// moment before a child executes unsupervised. A pending-approval/ child is still pre-
// spec-pass (the pass is what WRITES the section), an in-progress/ one is already claimed
// and grandfathered by construction, and archive/ is history. Forward-only in practice:
// at pass time no plan carried `program:` AND rested in `ready/`, so the first run reports
// zero — this lint catches the NEXT program child, not a backlog.
//
// Membership is the frontmatter `program:` key alone, not the prose "child N of M" Status
// line the plan body also describes: a lint must key on a machine-stamped field, and a
// free-prose sentence is neither reliably present nor reliably absent. The Status-line
// form stays a spec-pass (human/session) obligation, per coord/skills/spec-pass/SKILL.md.
//
// Pure core over entries = [{ path, content }], same split as findStageFolderViolations
// above, so the cases are unit-testable without a real git repo.
// Two review-round-1 findings shape how presence is decided, both CONFIRMED:
//   - the heading must be REAL, not one inside a ```md illustration — so the anchor is
//     `sectionBounds` (build-index-lib.mjs), the repo's fence-aware heading scanner, never
//     a bare `^##` regex. A plan showing the expected shape must not thereby satisfy it.
//   - an EMPTY section does not satisfy the check. The point is the premises themselves,
//     one line each; a heading with nothing under it is the shape without the content.
// Presence of at least one non-blank line is all that is judged — nothing semantic, same
// posture as the verdict blocker in plan-promotable-lib.mjs.
export const INHERITED_PREMISES_FOLDER_SCOPE = READY_FOLDER;
export const INHERITED_PREMISES_HEADING_RX = /^##\s+Inherited premises\b/im;

export function findInheritedPremisesViolations(entries) {
  const violations = [];
  for (const { path, content } of entries) {
    const rel = path.slice(PLANS_PREFIX.length);
    const status = rel.split('/')[0];
    if (status !== INHERITED_PREMISES_FOLDER_SCOPE) continue;
    // An empty/absent `program:` is the overwhelming majority — a standalone plan, which
    // this invariant says nothing about.
    if (!readFrontmatterScalar(content, 'program')) continue;
    const bounds = sectionBounds(content, INHERITED_PREMISES_HEADING_RX);
    // Fenced text inside the section is an ILLUSTRATION of the shape, not a premise
    // (review round 2) — stripped before the non-empty test.
    if (bounds && stripFencedBlocks(content.slice(bounds.start, bounds.end)).trim()) continue;
    violations.push(
      `  ${rel.split('/').pop()}: has a \`program:\` tag but no \`## Inherited premises\` ` +
        `section — a program child carries every mechanism it assumes BECAUSE THE PROGRAM ` +
        `assumed it, one line each, naming where in the code each can be verified (the ` +
        `parent keeps the same list under \`## Proven mechanisms\`). Add the section ` +
        `(node scripts/edit-plan.mjs <id> …) before this plan reaches the drain.`,
    );
  }
  return violations;
}

// IO wrapper — the same shared enumeration as checkStageFolderInvariant above.
export function checkInheritedPremisesInvariant() {
  const violations = findInheritedPremisesViolations(trackedPlanEntries());
  if (violations.length) {
    console.error('');
    console.error(
      'lint-plan-index: inherited-premises invariant FAILED — a program child in ready/ ' +
        'must carry its `## Inherited premises` section (plan 3943):',
    );
    violations.forEach((v) => console.error(v));
    console.error('');
    return 1;
  }
  return 0;
}

// ── Category-subfolder nesting invariant (plan 2678) ────────────────────────
// A plan may sit flat under its status folder, or one level down in an optional
// lowercase category folder (`parked/denmark/9-X-y.md`). Anything else — two levels of
// nesting, an uppercase/illegal category name, or ANY category under the flat-only
// `archive/` — is a lint failure here, on the FULL tracked corpus, from pre-push.
//
// This check is the enforcement half of the walker in build-index-lib.mjs: the walker
// makes an illegal path VISIBLE (it is classified and returned, never skipped), and this
// turns that visibility into a blocked push with a self-explaining message. Without it the
// rule would be documentation only — and a two-level plan would still enumerate, just into
// surfaces (INDEX bullets, board refs) whose paths nobody validated.
//
// Pure over a path list so the cases are unit-testable without a fixture tree; the message
// is planNestingViolation's, never a second restatement of the rule.
export function findNestingViolations(paths) {
  return classifyPlanPaths(paths, { plansPrefix: PLANS_PREFIX })
    .filter((e) => e.violation)
    .map((e) => `  ${e.violation}`);
}

export function checkNestingInvariant() {
  const violations = findNestingViolations(listTrackedPlanFiles());
  if (violations.length) {
    console.error('');
    console.error(
      'lint-plan-index: plan-folder nesting FAILED — a plan sits flat under its status ' +
        'folder, or ONE level down in a lowercase [a-z0-9-]+ category folder:',
    );
    violations.forEach((v) => console.error(v));
    console.error('');
    return 1;
  }
  return 0;
}

// ── Foreign-drift attribution (plan 1650, layer 2) ──────────────────────────
// A violation found by any check below can be INHERITED: a worktree branch cut from —
// or rebased onto (done-worktree's land spine) — a master tip whose committed INDEX
// was already drifted carries that drift verbatim, CANNOT heal it (coord docs are
// never committed on a worktree branch), and yet this lint blocked its push. One
// sibling's transient regen bug then stalls EVERY other session's land until someone
// incidentally heals master (the 2026-07-10 batch-pipeline-guards + plan-1631 double
// LAND_BLOCKED_HOLDING).
//
// Attribution is exact, not heuristic: if the branch's own commits (merge-base with
// origin/master → HEAD) touched NONE of the inputs the generated INDEX region and the
// plan-file checks derive from, then the branch's INDEX + tracked-plan set is
// byte-identical to the merge-base's — so any violation found in this tree existed at
// the merge-base and is master's to heal, not this push's to block on. The moment the
// branch touches ANY input, strict mode applies unchanged (the safe direction: a
// branch in the plan-doc-editing business owns its INDEX consistency in full).
//
// Scoped to non-master branches only — a master push CAN heal drift in the same
// motion, so it keeps the hard gate (and done-worktree's close-out regen relies on it).
// Fails CLOSED (returns false → strict) on any git error, including an unresolvable
// origin/master. `_exec` is the test seam for the git calls.
//
// The pathspec set includes the GENERATOR code, not just the data (plan 1650 review [0]):
// a branch that edits build-index's parse/render semantics can make `--check` disagree
// with a committed INDEX it never touched — that drift is the branch's OWN doing and must
// stay strict, or a coord-machinery change ships the exact committed-vs-regen split this
// plan exists to prevent. Exported for the test that pins the generator files' presence.
export const INDEX_INPUT_PATHSPECS = [
  'docs/INDEX.md',
  'docs/superpowers/plans',
  'docs/superpowers/specs',
  'coord.config.json',
  'scripts/build-index.mjs',
  'scripts/coord/build-index-lib.mjs',
  'scripts/coord/coord-config.mjs',
  'scripts/lint-plan-index.mjs',
  // plan 1664 review [0]/[1]: the actual git-attribution engine (branch/merge-base/diff/
  // status) now lives in drift-attribution-lib.mjs, not inline here — it MUST stay in this
  // list for the same reason lint-plan-index.mjs itself is: a branch that weakens the
  // fail-closed logic (or the merge-base/diff semantics) must not get to grade its own
  // change as "inherited" via the very logic it just edited.
  'scripts/coord/drift-attribution-lib.mjs',
];

// Thin wrapper over the shared core (plan 1664 — lifted so lint-board.mjs can reuse the
// same git-attribution plumbing against its own pathspec set). Behavior and signature
// unchanged from the plan-1650 original; every call site and test keeps working as-is.
// `env` (plan 1669) defaults to `{}`, NOT `process.env` — this keeps every test in this
// file (which calls `driftIsInherited({ _exec })` with no `env`) immune to whatever
// `.husky/pre-push` may have exported into the ambient process environment for the
// shared-rev-parse/merge-base optimization; only the real `main()` call site below
// opts in by passing `env: process.env` explicitly.
export function driftIsInherited({ repoRoot = REPO_ROOT, _exec = execFileSync, env = {} } = {}) {
  return computeDriftIsInherited({ repoRoot, pathspecs: INDEX_INPUT_PATHSPECS, _exec, env });
}

// Self-diagnosis (plan 2099): is THIS worktree's own copy of docs/INDEX.md simply
// behind origin/master's copy? Orthogonal to driftIsInherited above — see
// drift-attribution-lib.mjs's checkWorktreeCoordDocStale doc comment for why a
// worktree that authored/moved its own plan file can go strict there even when
// docs/INDEX.md itself was never touched by this branch. `localContent` is optional
// (review [1]): check 1's build-index --check failure has no in-process read to
// reuse and omits it, but check 2's archive-consistency failure already holds the
// raw INDEX.md text (checkArchiveConsistency's `indexContent`) and passes it
// through to avoid a second ~840KB readFileSync of the same file.
export function checkIndexStale({
  repoRoot = REPO_ROOT,
  _exec = execFileSync,
  env = {},
  localContent,
} = {}) {
  if (localContent === undefined) {
    try {
      localContent = readFileSync(join(repoRoot, INDEX_REL), 'utf8');
    } catch {
      return { stale: false, commitsBehind: null };
    }
  }
  return checkWorktreeCoordDocStale({ repoRoot, relPath: INDEX_REL, localContent, _exec, env });
}

// Prints the shared staleness diagnosis (drift-attribution-lib.mjs) when checkIndexStale
// reports `stale: true`. Called from both INDEX-related strict-failure paths in main()
// below (check 1 and the archive-consistency half of check 2) — NOT from the
// stage-folder-invariant check, which is about plan-file content, not docs/INDEX.md.
function reportIndexStalenessIfAny(env, localContent) {
  const staleness = checkIndexStale({ env, localContent });
  if (staleness.stale) {
    console.error(formatStaleWorktreeCoordDocMessage(INDEX_REL, staleness));
  }
}

// Shared WARN wording for a tolerated inherited violation — loud, so the pass is
// never mistaken for "no drift", and it names the master-side heal.
function warnInherited(what) {
  console.error('');
  console.error(
    `lint-plan-index: WARN — ${what} (the FAILED/STALE output above IS that violation), ` +
      `but this branch's own commits touched no plan/INDEX inputs since its merge-base ` +
      `with origin/master and the working tree is clean over them: the violation is ` +
      `INHERITED master drift, not this push's doing. Passing (plan 1650 layer 2).`,
  );
  console.error(
    '  Heal master (from the MAIN checkout): node scripts/build-index.mjs && ' +
      'node scripts/coord-edit.mjs --paths docs/INDEX.md --message "heal INDEX drift"',
  );
  console.error('');
}

// Telemetry (plan 1731): builds the memoized, "index"-marking lazy checker main() uses.
// computeFn/env are injectable (default to the real driftIsInherited call) so the "mark
// exactly once, on first call, regardless of outcome" contract is pinned by a unit test
// without an end-to-end git-repo drive of main(). The mark happens BEFORE computeFn()
// resolves — i.e. at the point of consulting attribution, not on its result — mirroring
// lint-board.mjs's checkDriftIsInheritedWithTelemetry. No-op unless .husky/pre-push
// exported COORD_PUSH_TELEMETRY_HITS_FILE (see push-telemetry-lib.mjs).
//
// computeFn's default CLOSES OVER the injected `env` param (plan-1731 review finding 2)
// rather than hardcoding `process.env`: a caller supplying only a custom `env` (leaving
// computeFn at its default) must have driftIsInherited consult that SAME env, not the
// real ambient one — the closure reads `env` lazily, when the returned checker is later
// invoked, by which point `env` (the second parameter) is fully bound; JS default-
// parameter evaluation order permits this because the arrow function body isn't
// executed at default-evaluation time, only its closure is formed.
export function makeInheritedDriftChecker(
  computeFn = () => driftIsInherited({ env }),
  env = process.env,
) {
  let inherited = null;
  return () => {
    if (inherited === null) markPushTelemetryHit('index', env);
    return (inherited ??= computeFn());
  };
}

export function main() {
  // Computed at most once per run; every tolerated check reuses the same attribution.
  const inheritedDrift = makeInheritedDriftChecker();
  // 1. Active region must equal what build-index would generate.
  try {
    // --check regenerates the active region in memory and exits 1 if the
    // on-disk INDEX differs. stdio inherited so build-index's own message shows.
    execFileSync('node', [BUILD_INDEX, '--check'], { cwd: REPO_ROOT, stdio: 'inherit' });
  } catch (err) {
    const code = typeof err.status === 'number' ? err.status : 2;
    if (code === 1) {
      if (inheritedDrift()) {
        warnInherited('docs/INDEX.md is out of sync with the plan files');
      } else {
        console.error('');
        console.error('lint-plan-index: docs/INDEX.md is out of sync with the plan files.');
        console.error(
          '  Fix:  node scripts/build-index.mjs && git add docs/INDEX.md   then re-push.',
        );
        console.error(
          '  (Only the generated region is checked; untracked/foreign plan docs never gate your push.)',
        );
        console.error(
          '  Emergency escape: git push --no-verify (but consider why INDEX drifted first).',
        );
        // plan 2099: this checkout's docs/INDEX.md may simply be behind origin/master's
        // (a sibling already fixed it) — the above "Fix" advice is misleading in that case.
        reportIndexStalenessIfAny(process.env);
        return 1;
      }
    } else {
      console.error('lint-plan-index: unexpected error invoking build-index.mjs', err.message);
      return 2;
    }
  }
  // 2. Archive narrative must not name a plan stranded outside plans/archive/.
  // 3. Stage/folder invariant (plan 1371 D7): pending-approval/ holds only stage: stub.
  // Both read the same tracked-plan inputs as check 1, so a violation a worktree branch
  // merely inherited at cut/rebase time is tolerated by the SAME attribution — a sibling's
  // momentarily-unrouted specced plan must not wedge an unrelated land (same blast-radius
  // class as INDEX drift). One shared tolerate-or-fail shape (review [7]); the
  // untracked-archive strand is local by construction and NEVER tolerated (review [1]).
  const laterChecks = [
    {
      run: () => {
        const { code, untrackedStrand, indexContent } = checkArchiveConsistency();
        return { code, neverTolerate: untrackedStrand, indexContent };
      },
      what: 'the archive narrative names a stranded plan',
      // plan 2099: this check's violations are read straight out of docs/INDEX.md's
      // archive narrative — a stale worktree copy of INDEX.md is a plausible cause,
      // UNLESS the violation is the untracked-strand kind (neverTolerate above),
      // which is a local-only .gitignore artifact with nothing to do with INDEX.md
      // drift and would make a "rebase" suggestion actively misleading.
      checksIndex: true,
    },
    {
      run: () => ({ code: checkStageFolderInvariant(), neverTolerate: false }),
      what: 'a specced plan rests in pending-approval/',
      // Reads plan-file frontmatter, not docs/INDEX.md — out of scope for the
      // INDEX-staleness diagnosis (deliberately no checksIndex flag).
    },
    {
      // 3b. Inherited premises (plan 3943). Inheritable for the same reason every check in
      // this list is: it reads tracked plan frontmatter, so one sibling's un-sectioned
      // program child must not wedge an unrelated land.
      run: () => ({ code: checkInheritedPremisesInvariant(), neverTolerate: false }),
      what: 'a program child in ready/ carries no `## Inherited premises` section',
      // Reads plan-file frontmatter, not docs/INDEX.md — no checksIndex flag.
    },
    {
      // 4. Category-subfolder nesting (plan 2678). Inheritable for the same reason the two
      // checks above are: it reads the tracked-plan path set, so a branch that touched none
      // of the INDEX inputs cannot have caused a violation it merely carried over from its
      // merge-base — and one sibling's mis-filed plan must not wedge every other land.
      run: () => ({ code: checkNestingInvariant(), neverTolerate: false }),
      what: 'a plan is filed in an illegal category subfolder',
      // Reads tracked plan PATHS, not docs/INDEX.md — no checksIndex flag.
    },
  ];
  for (const { run, what, checksIndex } of laterChecks) {
    const { code, neverTolerate, indexContent } = run(); // lazy: a hard fail above must not print later checks
    if (code === 0) continue;
    if (neverTolerate || !inheritedDrift()) {
      // indexContent (when the check's own run() already read docs/INDEX.md, e.g.
      // checkArchiveConsistency above) is reused here instead of a second read
      // (plan 2099 review [1]) — undefined for a check with no such read in hand.
      if (checksIndex && !neverTolerate) reportIndexStalenessIfAny(process.env, indexContent);
      return code;
    }
    warnInherited(what);
  }
  return 0;
}

// plan 1371: guarded entry point (mirrors lint-filename-execmodel-drift.mjs's pattern) so
// `findStageFolderViolations`/`checkStageFolderInvariant` can be imported by
// lint-plan-index.test.mjs for pure unit tests WITHOUT the module also running main() +
// process.exit() as an import side effect (which would kill the test process before any
// test() body ran — a real bug this file's prior bare `process.exit(main())` had, invisible
// until something first imported it rather than only invoking it as a script).
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exit(main());
}
